import{_ as t,o as e,c as s,a2 as r}from"./chunks/framework.CU6jEZEM.js";const i="/entismax/v4/assets/e4e09623a8b7560d-20261015000315-e8mphkm.D-q0Qhdb.png",o="/entismax/v4/assets/cf45f3964646ae9a-20261015000315-je4v3cl.DMEH3z9l.jpg",l="/entismax/v4/assets/f37640cc67a1f3c7-20261015000315-59890y8.CErQefnq.jpg",p="/entismax/v4/assets/d38c279dfe621bf4-20261015000315-utlej8r.Blgot6x4.png",n="/entismax/v4/assets/5658b6e4fe398f7c-20261015000315-pp7h7ym.CU2Rq47R.png",c="/entismax/v4/assets/fbfebcf36b611a73-20261015000315-cxlp6fq.BisQ1pZe.png",_="/entismax/v4/assets/5d2a86c6fb95820d-20261015000315-g1l2pet.DUE-mPXG.png",h="/entismax/v4/assets/19cf696372e625f6-20261015000315-hgbzul2.BYkwzp9C.jpg",d="/entismax/v4/assets/6a3da89811f0a453-20261015000315-86r4lq2.BqNVhl-y.png",k=JSON.parse('{"title":"初始化设置向导","description":"","frontmatter":{"title":"初始化设置向导","date":"2026-10-14T16:03:15.000Z","lastmod":"2026-11-20T09:44:18.000Z"},"headers":[],"relativePath":"guide/1017.md","filePath":"guide/EntisMAXIV/EntisMaxIV帮助文档/安装卸载说明/EntisMax软件安装/初始化设置向导.md"}'),m={name:"guide/1017.md"};function u(f,a,g,b,q,x){return e(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="初始化设置向导" tabindex="-1">初始化设置向导 <a class="header-anchor" href="#初始化设置向导" aria-label="Permalink to &quot;初始化设置向导&quot;">​</a></h1><hr><h4 id="第一次运行系统-会显示初始化设置向导-帮助启用系统" tabindex="-1">第一次运行系统，会显示初始化设置向导，帮助启用系统 <a class="header-anchor" href="#第一次运行系统-会显示初始化设置向导-帮助启用系统" aria-label="Permalink to &quot;第一次运行系统，会显示初始化设置向导，帮助启用系统&quot;">​</a></h4><h4 id="_1-注册界面" tabindex="-1">1:注册界面 <a class="header-anchor" href="#_1-注册界面" aria-label="Permalink to &quot;1:注册界面&quot;">​</a></h4><p>如果电脑没有插入授权的软件狗,则第一次运行会要求插入软件狗或输入临时试用的序列号,此时插入软件狗或输入序列号继续下一步</p><p>图1：</p><p><img src="'+i+'" alt=""></p><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h3><h4 id="_2-应用角色设置" tabindex="-1">2:应用角色设置 <a class="header-anchor" href="#_2-应用角色设置" aria-label="Permalink to &quot;2:应用角色设置&quot;">​</a></h4><p>此界面主要确定当前电脑运行的运行角色,是作为监控服务端运行还是查询客户端运行,如下图:</p><p>图2：</p><p><img src="'+o+'" alt=""></p><h4 id="_3-授权运行模块选择" tabindex="-1">3：授权运行模块选择 <a class="header-anchor" href="#_3-授权运行模块选择" aria-label="Permalink to &quot;3：授权运行模块选择&quot;">​</a></h4><p>界面中会列出当前软件狗已经授权的运行模块，此处可以确定本机实际运行的功能模块</p><p>图3：</p><p><img src="'+l+'" alt=""></p><h3 id="_4-数据库配置" tabindex="-1">4:数据库配置 <a class="header-anchor" href="#_4-数据库配置" aria-label="Permalink to &quot;4:数据库配置&quot;">​</a></h3><p>在运行初始化前，请先确保已经安装好合适的数据库版本，如当前安装的数据库设置同默认的不一致,则请点击按钮&quot;更改数据库连接&quot;修改,否则数据库无法连接,界面如下图</p><p>图4：</p><p><img src="'+p+'" alt=""></p><ul><li>如您已安装数据库.则请选上”我已安装…”的标签,<a href="#初始化操作员设定">执行下一步操作</a>.</li><li>如您选择的是本机不安装数据库服务器,则需要点击按钮“更改数据库连接”，配置数据库连接</li><li>如您上一步勾选的应用角色为客户端，则此处必须通过点击按钮“更改数据库连接”，配置数据库连接，因为客户端不能使用本机默认的数据库文件，需要连接监控服务端数据库</li></ul><h4 id="_5-数据库连接设置" tabindex="-1">5:数据库连接设置 <a class="header-anchor" href="#_5-数据库连接设置" aria-label="Permalink to &quot;5:数据库连接设置&quot;">​</a></h4><p>连接数据库有二个方式：</p><ul><li>连接到数据库文件，是系统默认的数据库连接方式,连接的数据库为软件安装目录下面的Database目录下面的数据库文件,如需要连接放置在其他地方的数据库文件,连点击浏览，选择相应的数据库文件即可。</li></ul><p>图5：</p><p><img src="'+n+'" alt=""></p><ul><li><p>连接到数据库名称，此种方式可以简化客户端,Web模块,其他应用模块或第三方服务端开发的系统连接我方的数据库,另外,如数据库服务器在另外一台电脑上，也需要使用此种方式来连接,如原来没有指定过数据库的逻辑名称,则</p></li><li><p>请先输入要使用的名称，然后点击&quot;附加数据库&quot;按钮，选择要附加的数据库即可。</p><p>图6： <img src="'+c+'" alt=""></p></li></ul><p>图7：</p><p><img src="'+_+'" alt=""></p><p></p><h4 id="_6-初始化操作员设定" tabindex="-1">6:初始化操作员设定 <a class="header-anchor" href="#_6-初始化操作员设定" aria-label="Permalink to &quot;6:初始化操作员设定&quot;">​</a></h4><p>系统已配置了默认操作员,如果不需要马上设置管理员新密码，可以直接跳过这一步,如确认系统没有配置任何默认操作员或需要重置管理员密码,则可以取消勾选项，然后执行帐号和权限的初始化操作。界面如下图:</p><p>图8：</p><p><img src="'+h+'" alt=""></p><ul><li>初始化会清除所有原有的帐号和权限配置，并初始化为默认数据，请慎用！</li></ul><p></p><h3 id="_8-初始化向导完成" tabindex="-1">8:初始化向导完成 <a class="header-anchor" href="#_8-初始化向导完成" aria-label="Permalink to &quot;8:初始化向导完成&quot;">​</a></h3><p><strong>运行到此处</strong>**,<strong>则初始化向导完成</strong>,<strong>您可以正常登录系统</strong>,<strong>进行相关设置</strong>.<strong>界面如图</strong>😗*</p><p><img src="'+d+'" alt=""></p>',39)])])}const v=t(m,[["render",u]]);export{k as __pageData,v as default};
